import urllib.request, json, tarfile, io, os

def get_sdist_url(version):
    url = f'https://pypi.org/pypi/astropy/{version}/json'
    with urllib.request.urlopen(url) as r:
        data = json.load(r)
    for u in data['urls']:
        if u['packagetype'] == 'sdist':
            return u['url']
    return None

for v in ['5.0', '5.1', '5.2']:
    u = get_sdist_url(v)
    print(v, u)
    if u:
        with urllib.request.urlopen(u) as r:
            raw = r.read()
        open(f'/tmp/astropy-{v}.tar.gz', 'wb').write(raw)
        print('  saved', len(raw))
"}

