import tarfile, re

def read_file(path, name):
    with tarfile.open(path) as t:
        for m in t.getmembers():
            if m.name.endswith(name):
                return t.extractfile(m).read().decode('utf-8')
    return None

def extract_methods(src, names):
    out = {}
    for name in names:
        m = re.search(rf'\n    def {name}\(.*?(?=\n    def |\nclass )', src, re.S)
        out[name] = m.group(0) if m else '<<MISSING>>'
    return out

for v in ['5.0', '5.1', '5.2']:
    q = read_file(f'/tmp/astropy-{v}.tar.gz', 'units/quantity.py')
    print('########## QUANTITY', v, '##########')
    for name in ['sum', 'nansum', 'mean', 'var', 'std']:
        print('=====', name, '=====')
        print(extract_methods(q, [name])[name])
"}

